#include <stddef.h>
#include <sys/types.h>
#include <unistd.h>

struct example_stats {
    size_t count;
    off_t total;
};

long example_sum(const long *values, size_t len) {
    long total = 0;
    for (size_t i = 0; i < len; i++) {
        total += values[i];
    }
    return total;
}

pid_t example_pid(void) {
    return getpid();
}

void example_collect(const long *values, size_t len, struct example_stats *out) {
    out->count = len;
    out->total = (off_t)example_sum(values, len);
}

use libc::{c_long, off_t, pid_t, size_t};

#[repr(C)]
pub struct ExampleStats {
    pub count: size_t,
    pub total: off_t,
}

unsafe extern "C" {
    fn example_sum(values: *const c_long, len: size_t) -> c_long;
    fn example_pid() -> pid_t;
    fn example_collect(values: *const c_long, len: size_t, out: *mut ExampleStats);
}

pub fn sum(values: &[i64]) -> i64 {
    let len = values.len() as size_t;
    let ptr = values.as_ptr().cast::<c_long>();
    unsafe { example_sum(ptr, len) as i64 }
}

pub fn pid() -> pid_t {
    unsafe { example_pid() }
}

pub fn collect(values: &[i64]) -> ExampleStats {
    let mut stats = ExampleStats { count: 0, total: 0 };
    let len = values.len() as size_t;
    let ptr = values.as_ptr().cast::<c_long>();
    unsafe { example_collect(ptr, len, &mut stats) };
    stats
}

mod ffi;

use libc::{getpid, pid_t};

fn main() {
    let values = [10_i64, 20, 30, 40];

    println!("sum (via C)    = {}", ffi::sum(&values));

    let stats = ffi::collect(&values);
    println!(
        "stats (via C)  = count={}, total={}",
        stats.count, stats.total
    );

    let c_pid: pid_t = ffi::pid();
    println!("pid (via C)    = {c_pid}");

    let libc_pid: pid_t = unsafe { getpid() };
    println!("pid (via libc) = {libc_pid}");
}
